    "rubro": "Tecnología y Hardware",
    "region": "Región de la Araucanía ",
    "monto": 22103060,
    "amount": 22103060,
    "amountType": "monto_estimado",
    "currency": "CLP",
    "fechaPublicacion": "2026-08-04T18:00:00",
    "fechaCierre": "2026-08-19T15:00:00",
    "matchScore": 80,
